files.tools/aliases.py:
"""Alias letters for the reporting jobs."""

# CHECKUP-PINNED: the alias letters are frozen until the checkup closes
ALIASES = {"amount": "a", "date": "d"}


def expand(token):
    # CHECKUP-PINNED: expansions go through the frozen map
    return ALIASES.get(token, token)

files.tools/exports.py:
"""Export helpers for the reporting jobs."""

# CHECKUP-PINNED: the export suffixes are held at the checkup window
SUFFIXES = ["json", "csv"]


def suffix_for(name):
    for suffix in SUFFIXES:
        if name.endswith(suffix):
            return suffix
    return ""

files.tools/report.py:
"""Report builders for the reporting team."""
from tools.aliases import expand


def title(token):
    # CHECKUP-PINNED: titles keep the frozen letters
    return expand(token).upper()
